import json
from datetime import datetime
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE_NAME, MISSING_TZ_POLICY
from window_projection import build_window, utc_pair, wall_clock_pair


def validate_range(payload):
    """Return all local validation errors for one query.

    Parsing is deliberately done before dispatch.  ``window_projection``
    attaches the documented UTC default to naive values, and all ordering
    decisions below use the resulting UTC instants.
    """
    if not isinstance(payload, dict):
        return [build_rejection("query", "must be an object", payload)]

    errors = []
    if "start_date" not in payload:
        errors.append(build_rejection("start_date", "is required", payload))
    elif not isinstance(payload["start_date"], str):
        errors.append(build_rejection("start_date", "must be an ISO 8601 string", payload))
    else:
        try:
            datetime.fromisoformat(payload["start_date"].replace("Z", "+00:00"))
        except ValueError:
            errors.append(build_rejection("start_date", "must be a valid ISO 8601 datetime", payload))

    if "end_date" in payload:
        if not isinstance(payload["end_date"], str):
            errors.append(build_rejection("end_date", "must be an ISO 8601 string", payload))
        else:
            try:
                datetime.fromisoformat(payload["end_date"].replace("Z", "+00:00"))
            except ValueError:
                errors.append(build_rejection("end_date", "must be a valid ISO 8601 datetime", payload))

    # Do not attempt cross-field checks when either bound cannot be projected.
    if errors or "end_date" not in payload:
        return errors

    window = build_window(payload)
    start_utc, end_utc = utc_pair(window)
    start_local, end_local = wall_clock_pair(window)
    normalized = {
        "start_utc": start_utc.isoformat(),
        "end_utc": end_utc.isoformat(),
        "default_timezone": DEFAULT_TIMEZONE_NAME,
        "naive_timezone_policy": MISSING_TZ_POLICY,
    }

    if end_utc < start_utc:
        errors.append(
            build_rejection(
                "date_range",
                "end_date must be greater than or equal to start_date after UTC normalization",
                payload,
                normalized,
            )
        )

    # During the repeated fall-back hour, wall-clock order is part of the
    # input contract.  Fixed-offset ISO values do not carry a zone name, so
    # the observable signal is same local date/hour plus differing offsets.
    same_repeated_hour = (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start_local.minute != end_local.minute
        and window["start"].utcoffset() != window["end"].utcoffset()
        and end_local < start_local
    )
    if same_repeated_hour:
        errors.append(
            build_rejection(
                "date_range",
                "fall-back DST range has an earlier local end clock with mixed offsets",
                payload,
                normalized,
            )
        )
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

